1→use serde::{Deserialize, Serialize};
2→
3→use super::role::Role;
4→
5→/// The nine board lanes in PRD §7 order.
6→///
7→/// `TimeWasteCost` is computed from the other lanes and never carries events.
8→#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
9→#[serde(rename_all = "snake_case")]
10→pub enum Lane {
11→    Intent,
12→    Orchestrator,
13→    Workers,
14→    Scrutiny,
15→    UserTesting,
16→    Integration,
17→    Human,
18→    Outside,
19→    TimeWasteCost,
20→}
21→
22→impl Lane {
23→    /// Board order, left to right.
24→    pub const ALL: [Lane; 9] = [
25→        Lane::Intent,
26→        Lane::Orchestrator,
27→        Lane::Workers,
28→        Lane::Scrutiny,
29→        Lane::UserTesting,
30→        Lane::Integration,
31→        Lane::Human,
32→        Lane::Outside,
33→        Lane::TimeWasteCost,
34→    ];
35→
36→    /// 1-based lane number as in the PRD table.
37→    pub fn number(self) -> u8 {
38→        match self {
39→            Lane::Intent => 1,
40→            Lane::Orchestrator => 2,
41→            Lane::Workers => 3,
42→            Lane::Scrutiny => 4,
43→            Lane::UserTesting => 5,
44→            Lane::Integration => 6,
45→            Lane::Human => 7,
46→            Lane::Outside => 8,
47→            Lane::TimeWasteCost => 9,
48→        }
49→    }
50→
51→    pub fn name(self) -> &'static str {
52→        match self {
53→            Lane::Intent => "Intent",
54→            Lane::Orchestrator => "Orchestrator",
55→            Lane::Workers => "Workers",
56→            Lane::Scrutiny => "Validators, scrutiny",
57→            Lane::UserTesting => "Validators, user testing",
58→            Lane::Integration => "Integration",
59→            Lane::Human => "Human",
60→            Lane::Outside => "Outside",
61→            Lane::TimeWasteCost => "Time, Waste, Cost and models",
62→        }
63→    }
64→
65→    /// Lane of an event whose kind does not fix one (an `Unknown` event): the role decides.
66→    /// An unresolved role lands in Workers, where child sessions live.
67→    pub fn for_role(role: Role) -> Lane {
68→        match role {
69→            Role::Orchestrator => Lane::Orchestrator,
70→            Role::Worker | Role::Unresolved => Lane::Workers,
71→            Role::ScrutinyValidator => Lane::Scrutiny,
72→            Role::UserTestingValidator => Lane::UserTesting,
73→            Role::Human => Lane::Human,
74→            Role::External => Lane::Outside,
75→        }
76→    }
77→}
