## 1
1→//! The skeleton mapper over the S capture: every raw line becomes one `Unknown` event.
2→
3→use std::path::{Path, PathBuf};
4→
5→use observatory_core::config::IngestConfig;
6→use observatory_core::ingest::{JsonlSource, RawRecord, Source, mapping_version_of};
7→use observatory_core::mapping::{Mapper, MappingVersion, SessionMeta};
8→use observatory_core::model::{Event, EventKind, Lane, Role, SessionId, SourcePtr};
9→
10→const SLUG: &str = "2026-10-22-observatory-v1-s";
11→
12→fn fixture(extension: &str) -> PathBuf {
13→    Path::new(env!("CARGO_MANIFEST_DIR"))
14→        .join("../../fixtures/streams")
15→        .join(format!("{SLUG}.{extension}"))
16→}
17→
18→fn read_all(source: &mut JsonlSource) -> Vec<RawRecord> {
19→    let mut records = Vec::new();
20→    for _ in 0..100_000 {
21→        records.extend(source.next_batch().expect("batch reads"));
22→        if source.at_eof() {
23→            records.extend(source.drain_partial());
24→            return records;
25→        }
26→    }
27→    panic!("source never reached the end of the file");
28→}
29→
30→fn replay(path: &Path) -> (Vec<RawRecord>, Vec<Event>) {
31→    let mut source = JsonlSource::open(path, &IngestConfig::default()).expect("fixture opens");
32→    let version = mapping_version_of(path).expect("capture header is readable");
33→    let mut mapper = Mapper::new(SessionMeta::root(source.root_session_id().clone()), version);
34→    let records = read_all(&mut source);
35→    let events = records
36→        .iter()
37→        .flat_map(|record| mapper.map(record))
38→        .collect();
39→    (records, events)
40→}
41→
42→#[test]
43→fn replay_counts_every_line_of_a_capture() {
44→    let path = fixture("jsonl");
45→    let lines = std::fs::read(&path)
46→        .unwrap()
47→        .split_inclusive(|b| *b == b'\n')
48→        .count();
49→
50→    let (records, events) = replay(&path);
51→
52→    assert_eq!(records.len(), lines);
53→    assert_eq!(events.len(), lines);
54→    assert!(lines > 0);
55→    assert!(
56→        events
57→            .iter()
58→            .all(|event| matches!(event.kind, EventKind::Unknown { .. })),
59→        "the S mapper knows no kind but Unknown"
60→    );
61→}
62→
63→#[test]
64→fn every_replayed_event_points_at_its_own_line() {
65→    let path = fixture("jsonl");
66→    let file = std::fs::read(&path).unwrap();
67→
68→    let (_, events) = replay(&path);
69→
70→    for event in &events {
71→        let SourcePtr::Jsonl {
72→            byte_offset,
73→            byte_len,
74→            ..
75→        } = &event.source
76→        else {
77→            panic!("replayed events point into a Jsonl file");
78→        };
79→        let start = *byte_offset as usize;
80→        let line = &file[start..start + *byte_len as usize];
81→        let raw: serde_json::Value = serde_json::from_slice(line).expect("fixture lines are JSON");
82→        let EventKind::Unknown { raw_type } = &event.kind else {
83→            panic!("expected Unknown");
84→        };
85→        assert_eq!(raw["type"].as_str(), Some(raw_type.as_str()));
86→        assert_eq!(
87→            event.id.0,
88→            format!("{}:{start}:0", event.session_id.as_ref().unwrap())
89→        );
90→    }
91→}
92→
93→#[test]
94→fn replayed_events_carry_the_root_session_the_orchestrator_lane_and_the_header_version() {
95→    let (_, events) = replay(&fixture("jsonl"));
96→
97→    let first = events.first().unwrap();
98→    assert_eq!(
99→        first.session_id,
100→        Some(SessionId("e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c".to_owned()))
101→    );
102→    assert_eq!(first.role, Role::Orchestrator);
